head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > E > onviewchange]<br/>Calendar 컴포넌트에서 사용자의 조작에 의해 선택 날짜가 변경될 때 발생합니다.",
    "validation" : [
        "Calendar 컴포넌트에서 사용자의 조작에 의해 선택 날짜가 변경될 때 onviewchange 이벤트가 발생합니다.",
        "메소드를 사용하여 선택 날짜가 변경된 경우에는 onviewchange 이벤트가 발생하지 않습니다.",
        "info 파라미터로 변경 전후의 값을 포함하는 객체가 전달됩니다.",
        "info.oldValue 속성으로 변경 전의 값이 getValue() 반환값 형태 문자열로 전달됩니다.",
        "info.newValue 속성으로 변경된 값이 getValue() 반환값 형태 문자열로 전달됩니다.",
        "선택일의 전/후 값이 동일하면 onviewchange 이벤트가 발생하지 않습니다.",
        "날짜/연도/월 등 모든 종류의 값 변경에 대해 onviewchange 이벤트가 발생합니다.",
        "날짜 셀 클릭 시 onchange -> ondateselect -> onviewchange 순서로 이벤트가 발생합니다.",
        "SelectBox 에서 연도/월 변경 시 onchange -> onviewchange -> [onyearselect/onmonthselect] 순서로 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내
    $c.gcm.createLabel('label="[수동 테스트 안내] (1) 활성화된 날짜 셀 클릭 시: onchange → ondateselect → onviewchange 순서로 발생, (2) 헤더의 연도/월 SelectBox 변경 시: onchange → onviewchange → [onyearselect/onmonthselect] 순서로 발생, (3) 동일한 날짜 셀 재클릭 시 값 변경이 없어 onviewchange 미발생"', '', 'label1');

    // calendarValueType=yearMonthDate: 날짜/연도/월 변경 검증
    let properties = {
        calendarValueType : "yearMonthDate"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "ondateselect", "onviewchange", "onyearselect", "onmonthselect"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// 메소드 호출에 의한 onviewchange 미발생 검증 (validation 2)
scwin.btn_callMethod_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1.gotoCalendar('20251225') 호출=====");
    target1.gotoCalendar('20251225');
};



// 선택된 날짜가 변경될 때 발생 (validation 8, 9 - 이벤트 순서 검증)
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생]");
};



// 날짜 셀 클릭 시 발생 (validation 8 - 이벤트 순서 검증)
scwin.target1_ondateselect = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[ondateselect 발생]");
};



// SelectBox 에서 연도 변경 시 발생 (validation 9 - 이벤트 순서 검증)
scwin.target1_onyearselect = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onyearselect 발생]");
};



// SelectBox 에서 월 변경 시 발생 (validation 9 - 이벤트 순서 검증)
scwin.target1_onmonthselect = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onmonthselect 발생]");
};



// 사용자의 조작에 의해 선택일이 변경된 경우 발생 (validation 1, 3, 4, 5, 6, 7, 8, 9)
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
};
